//! Player collision radius and boss sprite scale, from PokéSurvivor sprites.js and enemy.js
//! at e868b5e. Idle frame in js/data/sprites-meta.js. Generated; do not edit by hand.
//! playerRadius = min(18, bodyRadius(dex, playerScale(dex))) — sprites.js:144-151.
//! bossScale = clamp(round(110 / (ay*PX) * 2) / 2, 1, 2) — enemy.js:16-22. 0 means no sprite.

pub fn player_radius(dex: u32) -> Option<f64> {
    let i = dex as usize;
    if i >= PLAYER.len() || PLAYER[i] == 0 {
        return None;
    }
    Some(PLAYER[i] as f64 / 100.0)
}

pub fn boss_scale(dex: u32) -> Option<f64> {
    let i = dex as usize;
    if i >= BOSS.len() || BOSS[i] == 0 {
        return None;
    }
    Some(if BOSS[i] == 3 { 1.5 } else { BOSS[i] as f64 })
}

