#[cfg(test)]
mod tests {
    use super::{boss_scale, player_radius};

    #[test]
    fn shrunk_player_radii_match_sprites_js() {
        // playerScale shrinks these below the raw body radius; the cap of 18 still applies.
        let shrunk = [
            (22, 16.50),
            (161, 9.90),
            (230, 16.50),
            (330, 13.20),
            (491, 15.40),
            (714, 13.20),
            (773, 13.20),
            (781, 17.16),
            (787, 13.20),
            (804, 16.50),
            (849, 13.20),
            (874, 15.40),
            (905, 13.20),
        ];
        for (dex, r) in shrunk {
            let got = player_radius(dex).unwrap();
            assert!((got - r).abs() < 1e-9, "dex {dex}: {got} != {r}");
            assert!(got <= 18.0);
        }
        assert_eq!(player_radius(0), None);
    }

    #[test]
    fn every_radius_is_capped_and_boss_scale_is_1_1_5_or_2() {
        let mut players = 0;
        let mut scales = [0u32; 4];
        for dex in 0..1025u32 {
            if let Some(r) = player_radius(dex) {
                assert!(r > 0.0 && r <= 18.0, "dex {dex} radius {r}");
                players += 1;
            }
            match boss_scale(dex) {
                None => scales[0] += 1,
                Some(1.0) => scales[1] += 1,
                Some(1.5) => scales[2] += 1,
                Some(2.0) => scales[3] += 1,
                Some(other) => panic!("dex {dex} boss scale {other}"),
            }
        }
        assert_eq!(players, 966);
        // All 966 sprites, not only the boss-eligible subset.
        assert_eq!(scales, [59, 31, 294, 641]);
    }
}

